from math import comb

def calculate_mono_triangles(n_r, n_b):
    return comb(n_r, 3) + comb(n_b, 3)

N = 6
results = {}
for n_r in range(N + 1):
    n_b = N - n_r
    m = calculate_mono_triangles(n_r, n_b)
    results[(n_r, n_b)] = m

print(results)

